    "db_user_data.sh.tftpl": "#!/bin/bash
set -euo pipefail

# Install Docker
sudo dnf install -y docker
sudo systemctl enable --now docker

# Wait for the attached EBS volume to appear
DEVICE="/dev/disk/by-id/aws-${aws_ebs_volume.postgres_data.id}"
for i in {1..30}; do
  if [ -e "$${DEVICE}" ]; then break; fi
  sleep 2
done

# Determine the block device (e.g., /dev/nvme1n1) from the symlink
BLOCK_DEVICE=$(readlink -f "$${DEVICE}")

# Format if not already formatted
if ! blkid -o value -s TYPE "$${BLOCK_DEVICE}"; then
  mkfs.ext4 "$${BLOCK_DEVICE}"
fi

# Create mount point and mount the volume
mkdir -p $${data_path_host}
mount "$${BLOCK_DEVICE}" $${data_path_host}

# Ensure the mount persists across reboots (optional, not required for idempotent bootstrap)
# echo "$${BLOCK_DEVICE} $${data_path_host} ext4 defaults,nofail 0 2" >> /etc/fstab

# Pull and run PostgreSQL container with data directory bound to the mounted volume
docker pull $${postgres_image}

docker run -d \
  --name postgres-container \
  -e POSTGRES_DB=$${postgres_db} \
  -e POSTGRES_USER=$${postgres_user} \
  -e POSTGRES_PASSWORD=$${postgres_password} \
  -v $${data_path_host}:$${data_path_host} \
  -p 5432:5432 \
  $${postgres_image}
